function benchmark_VectorizedRotateVec3
% BENCHMARK two implementations to apply page-wise DCMs to 3xN vectors.
% - Vectorized: pagemtimes
% - Loop:       explicit per-page multiply
%
% Results printed as a table with median runtimes and speedup.
% NOTE: mainly generated by ChatGPT 5

%% Settings
Ns          = [1e2, 1e3, 1e4, 5e4];   % number of pages/vectors
idx_mode    = 'full';                 % 'full' or 'sparse'
sparse_step = 2;                      % use every k-th page if idx_mode='sparse'
repeats     = 5;                      % timeit repeats (median reported)
dtype       = 'double';               % 'double' or 'single'
rng(0);

%% Header
fprintf('Benchmarking VectorizedRotateVec3 implementations\n');
fprintf('dtype=%s | idx_mode=%s\n\n', dtype, idx_mode);

all_rows = [];

for Ni = 1:numel(Ns)
    N = Ns(Ni);

    % --- Build inputs (outside timed region) ---
    [DCM, V] = make_test_data(N, dtype);
    switch idx_mode
        case 'full'
            idx = 1:N;
        case 'sparse'
            idx = 1:sparse_step:N;
        otherwise
            error('Unknown idx_mode.');
    end

    % --- Define callables ---
    f_vec  = @() VectorizedRotateVec3(DCM, V, idx);
    f_loop = @() ApplyDCMtoArray_loop (DCM, V, idx);

    % --- Warm up and correctness check ---
    out_vectorized = f_vec();  
    out_loop = f_loop();

    % Compare only the indexed cols
    max_abs_err = max(abs(out_vectorized(:,idx) - out_loop(:,idx)), [], 'all');
    if ~(max_abs_err <= 1e-10 || (strcmp(dtype,'single') && max_abs_err <= 1e-6))
        error('Mismatch detected (max abs err = %.3g).', max_abs_err);
    end

    % --- Benchmark ---
    t_vec  = 0.0;
    t_loop = 0.0;
    for idTrial = 1:repeats
        t_vec  = t_vec + timeit(f_vec,  1);
        t_loop = t_loop + timeit(f_loop, 1);
    end

    t_vec  = t_vec / repeats;
    t_loop = t_loop / repeats;

    speed  = t_loop / t_vec;

    all_rows = [all_rows; N, numel(idx), t_vec, t_loop, speed]; %#ok<AGROW>
    fprintf('N=%-7d | used=%-7d | vec=%.6f s | loop=%.6f s | speedup=%.2fx\n', ...
        N, numel(idx), t_vec, t_loop, speed);
end

% --- Display as table ---
T = array2table(all_rows, 'VariableNames', ...
    {'N_pages','Used_indices','Vec_time_s','Loop_time_s','Loop_over_Vec'});
disp(T);

end

function out = ApplyDCMtoArray_loop(DCM, vecs, idx)
% Loop version (no reshape), minimal allocations. Writes into preallocated out.
% DCM:  [3x3xN], vecs: [3xN], idx: indices into pages/columns
out = zeros(3,size(DCM,3));
for k = 1:numel(idx)
    j = idx(k);
    out(:, j) = DCM(:,:,j) * vecs(:, j);
end
end

%==================== Utilities ====================%

function [DCM, V] = make_test_data(N, dtype)
% Create random rotation matrices and random 3xN vectors (not timed)
V = cast(randn(3, N), dtype);

% Create valid rotation matrices cheaply: random axis-angle
theta = cast(2*pi*rand(1,N), dtype);
ax    = normalize_cols(cast(randn(3,N), dtype));
DCM   = zeros(3,3,N, dtype);
I3    = eye(3, dtype);

% Rodrigues' formula per page (vectorized-ish)
% R = I + sin(t)[a]_x + (1-cos(t))[a]_x^2
ax_x   = skew_batch(ax);                   % 3x3xN
sT     = reshape(sin(theta), 1,1,[]);
cT     = reshape(cos(theta), 1,1,[]);
for i = 1:N
    A  = ax_x(:,:,i);
    DCM(:,:,i) = I3 + sT(:,:,i)*A + (1 - cT(:,:,i))*(A*A);
end
end

function S = skew_batch(a)
% Build [a]_x for each column of a (3xN) -> 3x3xN
N = size(a,2);
S = zeros(3,3,N, 'like', a);
ax = a(1,:); ay = a(2,:); az = a(3,:);
S(1,2,:) = -az; S(1,3,:) =  ay;
S(2,1,:) =  az; S(2,3,:) = -ax;
S(3,1,:) = -ay; S(3,2,:) =  ax;
end

function A = normalize_cols(A)
% Normalize each column to unit norm
n = vecnorm(A,2,1);
n(n==0) = 1;
A = A ./ n;
end
